package com.skillswap.web;

import com.skillswap.model.*;
import com.skillswap.repo.*;
import org.springframework.http.HttpStatus;
import org.springframework.security.core.Authentication;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import java.util.*;

@RestController @RequestMapping("/api")
public class LearningController {
 private final ApiSupport support;private final CourseRepository courses;private final EnrollmentRepository enrollments;private final LessonRepository lessons;private final LessonCompletionRepository completions;private final MaterialFileRepository files;
 public LearningController(ApiSupport support,CourseRepository courses,EnrollmentRepository enrollments,LessonRepository lessons,LessonCompletionRepository completions,MaterialFileRepository files){this.files=files;this.support=support;this.courses=courses;this.enrollments=enrollments;this.lessons=lessons;this.completions=completions;}
 private Map<String,Object> preview(Lesson l){return Map.of("id",l.id,"title",l.title,"position",l.position,"estimatedMinutes",l.estimatedMinutes);}
 private Map<String,Object> full(Lesson l){Map<String,Object> data=new LinkedHashMap<>(preview(l));data.put("content",l.content);data.put("videoFileId",l.videoFileId==null?0:l.videoFileId);data.put("notesFileId",l.notesFileId==null?0:l.notesFileId);data.put("videoUrl",l.videoUrl==null?"":l.videoUrl);return data;}
 private Course getCourse(Long id){return courses.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Course not found"));}
 private boolean owns(AppUser u,Course c){return u.admin||c.mentor.id.equals(u.id);}
 @GetMapping("/catalog/courses/{courseId}/syllabus")public List<Map<String,Object>> syllabus(@PathVariable Long courseId){Course c=getCourse(courseId);ApiSupport.require(c.published,"Course unavailable");return lessons.findByCourseIdOrderByPositionAsc(courseId).stream().map(this::preview).toList();}
 @GetMapping("/learning/course/{courseId}")public Map<String,Object> detail(Authentication a,@PathVariable Long courseId){AppUser me=support.me(a);Course c=getCourse(courseId);ApiSupport.require(owns(me,c)||enrollments.existsByLearnerIdAndCourseId(me.id,c.id),"Enroll to access course lessons");var all=lessons.findByCourseIdOrderByPositionAsc(courseId);var done=completions.findByLearnerIdAndLessonCourseId(me.id,courseId).stream().map(x->x.lesson.id).toList();return Map.of("course",ApiSupport.course(c),"lessons",all.stream().map(this::full).toList(),"completedIds",done,"completedCount",done.size(),"totalLessons",all.size(),"canManage",owns(me,c));}
 @PostMapping("/learning/lessons/{lessonId}/completion") @Transactional public Map<String,Object> completion(Authentication a,@PathVariable Long lessonId,@RequestBody Map<String,Object> form){AppUser me=support.me(a);Lesson l=lessons.findById(lessonId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));Enrollment e=enrollments.findByLearnerIdAndCourseId(me.id,l.course.id).orElseThrow(()->new ResponseStatusException(HttpStatus.FORBIDDEN,"Only enrolled learners may track progress"));boolean complete=Boolean.parseBoolean(ApiSupport.str(form,"completed"));var old=completions.findByLearnerIdAndLessonId(me.id,lessonId);if(complete&&old.isEmpty()){LessonCompletion lc=new LessonCompletion();lc.learner=me;lc.lesson=l;completions.save(lc);}else if(!complete&&old.isPresent())completions.delete(old.get());long count=completions.findByLearnerIdAndLessonCourseId(me.id,l.course.id).size();long total=lessons.countByCourseId(l.course.id);e.progress=total==0?0:(int)Math.min(100,count*100/total);enrollments.save(e);return Map.of("completed",complete,"completedCount",count,"totalLessons",total,"progress",e.progress);}
 @PostMapping("/learning/course/{courseId}/lessons") @Transactional public Map<String,Object> addLesson(Authentication a,@PathVariable Long courseId,@RequestBody Map<String,Object> form){AppUser me=support.me(a);Course c=getCourse(courseId);if(!owns(me,c))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only this mentor can manage lessons");String title=ApiSupport.str(form,"title"),content=ApiSupport.str(form,"content");ApiSupport.require(title.length()>=3&&title.length()<=180,"Lesson title must be 3–180 characters");ApiSupport.require(content.length()>=20&&content.length()<=8000,"Lesson notes must be 20–8000 characters");Lesson l=new Lesson();l.course=c;l.position=(int)lessons.countByCourseId(courseId)+1;l.title=title;l.content=content;lessons.save(l);c.lessons=l.position;courses.save(c);return full(l);}
 @PatchMapping("/learning/lessons/{lessonId}") @Transactional public Map<String,Object> editLesson(Authentication a,@PathVariable Long lessonId,@RequestBody Map<String,Object> form){AppUser me=support.me(a);Lesson l=lessons.findById(lessonId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(!owns(me,l.course))throw new ResponseStatusException(HttpStatus.FORBIDDEN);if(form.containsKey("title")){String title=ApiSupport.str(form,"title");ApiSupport.require(title.length()>=3&&title.length()<=180,"Lesson title must be 3–180 characters");l.title=title;}if(form.containsKey("videoUrl")){String url=ApiSupport.str(form,"videoUrl");ApiSupport.require(url.isEmpty()||(url.startsWith("https://")&&url.matches("(?i)^https://[^\\s]+\\.mp4(?:\\?[^\\s]*)?$")),"Use an HTTPS direct MP4 link");l.videoUrl=url;}
 if(form.containsKey("notesFileId")){long id=ApiSupport.num(form,"notesFileId",0);if(id==0)l.notesFileId=null;else{MaterialFile file=files.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));ApiSupport.require(Objects.equals(file.courseId,l.course.id)&&file.owner.id.equals(me.id)&&"application/pdf".equals(file.mime),"PDF must be uploaded for this course");l.notesFileId=id;}}
 if(form.containsKey("videoFileId")){long id=ApiSupport.num(form,"videoFileId",0);if(id==0)l.videoFileId=null;else{MaterialFile file=files.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));ApiSupport.require(Objects.equals(file.courseId,l.course.id)&&file.owner.id.equals(me.id)&&"video/mp4".equals(file.mime),"MP4 must be uploaded for this course");l.videoFileId=id;}}
 if(form.containsKey("content")){String content=ApiSupport.str(form,"content");ApiSupport.require(content.length()>=20&&content.length()<=8000,"Lesson content must be 20–8000 characters");l.content=content;}lessons.save(l);return full(l);}
}
